    tower.seenIntro = Boolean(tower.seenIntro);
    tower.bestFloor = Math.max(0, Math.floor(Number(tower.bestFloor) || 0));
    tower.totalRuns = Math.max(0, Math.floor(Number(tower.totalRuns) || 0));
    tower.currency = Math.max(0, Math.floor(Number(tower.currency) || 0));
    tower.permanentUpgrades = tower.permanentUpgrades && typeof tower.permanentUpgrades === "object" ? tower.permanentUpgrades : {};
    tower.codexEntries = Array.isArray(tower.codexEntries) ? [...new Set(tower.codexEntries.filter((entry) => typeof entry === "string"))] : [];
    tower.returnRegionIndex = Number.isInteger(tower.returnRegionIndex) && tower.returnRegionIndex >= 0 && tower.returnRegionIndex < REGIONS.length ? tower.returnRegionIndex : state2.regionIndex;
    tower.returnPosition = tower.returnPosition && Number.isFinite(tower.returnPosition.x) && Number.isFinite(tower.returnPosition.y) ? { x: tower.returnPosition.x, y: tower.returnPosition.y } : null;
