  handleInput(event){const input=event.target;if(input.matches("[data-asset-search],[data-asset-region],[data-asset-category],[data-asset-role],[data-asset-source],[data-asset-composition],[data-asset-collision],[data-asset-special]"))this.renderAssets();if(input.matches("[data-editor-opacity]")){this.editor.overlayOpacity=number(input.value,.48);this.preferences.overlayOpacity=this.editor.overlayOpacity;this.savePreferences();}}
