  toggleEditorTest(button){const testing=this.editor.overlay.style.pointerEvents!=="none";this.editor.overlay.style.pointerEvents=testing?"none":"auto";button.classList.toggle("active",testing);button.textContent=testing?"Voltar a editar":"Testar movimento";testing?this.context.getEngine()?.resume?.():this.context.getEngine()?.stop?.();}
