  async copyCoordinates(){const state=this.context.getState(),engine=this.context.getEngine(),position=state.gameMode==="tower"?engine.position:state.position;await copyText(stableStringify({engine:state.gameMode,region:state.regionIndex,floor:engine.floor?.floor||null,x:position.x,y:position.y,cellX:Math.floor(position.x/64),cellY:Math.floor(position.y/64)},2));this.context.notify?.("Coordenadas copiadas","Prontas para colar no código.","good");}
  async preloadVisual(route,variant,form){const front=this.context.formSprite(route,form,"front",variant),fallback=this.context.characterArt(route,variant),results=[];for(const direction of["front","back","left","right"]){const exact=this.context.formSprite(route,form,direction,variant),image=await this.context.cache.loadFirst(exact,[front,fallback]);results.push({direction,exact,resolved:this.context.cache.aliases.get(exact)||exact,visible:Boolean(image&&image.naturalWidth&&image.naturalHeight)});}return results;}
