  async applyVisual(){const state=this.context.getState(),route=this.panel.querySelector("[data-dev-route]").value==="timbo"?"timbo":"lucas",variant=this.panel.querySelector("[data-dev-variant]").value==="feminino"?"feminino":"masculino",form=this.panel.querySelector("[data-dev-form]").value,results=await this.preloadVisual(route,variant,form),invalid=results.filter(result=>!result.visible);if(invalid.length){this.panel.querySelector("[data-dev-sprite-result]").textContent=`Troca cancelada: ${invalid.length} direção(ões) sem imagem ou fallback.`;return;}const previousHero=this.context.combat?.party?.find(actor=>actor.hero),previousSprite=previousHero?this.context.combat.actorSprite(previousHero):null;state.route=route;state.visualVariant=variant;state.activeForm=form;if(!state.unlockedForms.includes(state.activeForm))state.unlockedForms.push(state.activeForm);await this.context.refreshCharacterVisuals?.();if(previousHero){previousHero.name=state.route==="timbo"?"Timbó":"Lucas";previousHero.img=results.find(result=>result.direction==="front")?.resolved||this.context.characterArt(state.route,state.visualVariant);previousHero.lastVisibleImg=previousSprite;previousHero.imgFallbacks=[previousSprite,this.context.characterArt(state.route,state.visualVariant)].filter(Boolean);this.context.combat.render?.();}this.context.updateHud(true);this.panel.querySelector("[data-dev-sprite-result]").textContent="Forma carregada nas quatro direções sem transparência.";}
