  renderAssets(){const value=selector=>this.panel.querySelector(selector)?.value||"",query=value("[data-asset-search]").toLowerCase(),region=value("[data-asset-region]"),category=value("[data-asset-category]"),role=value("[data-asset-role]"),source=value("[data-asset-source]"),composition=value("[data-asset-composition]"),collision=value("[data-asset-collision]"),special=value("[data-asset-special]");const assets=TOWER_ASSETS.filter(asset=>(!query||`${asset.name} ${asset.variantGroup} ${asset.compositionSet} ${asset.sourceCategory}`.toLowerCase().includes(query))&&(!region||asset.region===region)&&(!category||asset.category===category)&&(!role||asset.tileRole===role)&&(!source||asset.sourceCategory===source)&&(!composition||asset.compositionSet===composition)&&(!collision||asset.collision===collision)&&(!special||Boolean(asset[special]))).slice(0,120);this.panel.querySelector("[data-asset-grid]").innerHTML=assets.map(asset=>`<button class="dev-asset" data-asset-id="${asset.id}" title="${escapeHtml(asset.name)} · ${asset.scaleClass} · ${asset.recommendedWorldHeight}px"><img loading="lazy" src="${escapeHtml(asset.path)}"><span>${escapeHtml(asset.name)}</span></button>`).join("")||"<p>Nenhum asset encontrado.</p>";}
