    if(selection.kind==="prop")fields+=`${field("height","Altura")}${field("scalePercent","Escala %",Math.round((value.height/Math.max(1,value.recommendedWorldHeight||value.height))*100))}${field("anchorOffsetX","Âncora X")}${field("anchorOffsetY","Âncora Y")}${field("sortOffsetY","Sort Y")}${field("collisionOffsetX","Colisão X")}${field("collisionOffsetY","Colisão Y")}${field("footprintW","Colisão L",value.footprint?.[0])}${field("footprintH","Colisão A",value.footprint?.[1])}${field("shadowWidth","Sombra L")}${field("shadowHeight","Sombra A")}${field("shadowOffsetY","Sombra Y")}${field("shadowOpacity","Opacidade",value.shadowOpacity,"number",".01")}${field("rotation","Rotação °",value.rotation||0)}<div class="dev-field"><label>Colisão</label><select data-prop="collision">${["none","traversable","footprint","solid","hazard"].map(option=>`<option ${value.collision===option?"selected":""}>${option}</option>`).join("")}</select></div><div class="dev-field"><label>Camada</label><input data-prop="layer" value="${escapeHtml(value.layer||"")}"></div>${check("shadowEnabled","Sombra",value.shadowEnabled!==false)}${check("mirror","Espelhar",value.mirror,!value.canMirror)}${check("proportionalCollision","Escala proporcional",value.proportionalCollision!==false)}`;
