      document.querySelector("#tower-hud-objective").textContent = objective ? `${objective.label}${objective.targets ? ` (${objective.progress || 0}/${objective.targets}${objective.id === "explore" ? "%" : ""})` : ""}` : "Ou\xE7a a geometria.";
      document.querySelector("#tower-hud-seed").textContent = `SEMENTE ${run.seed}`;
      document.querySelector("#tower-hud-pulse").textContent = run.floor % 10 === 0 ? "PULSO CR\xCDTICO" : run.floor % 5 === 0 ? "PULSO ALTO" : run.floor > 20 ? "PULSO CRESCENTE" : "PULSO BAIXO";
      document.querySelector("#tower-hud-mutations").textContent = upgrades.length ? upgrades.slice(0, 2).join(" \u2022 ") : "SEM MELHORIAS";
      document.querySelector("#tower-hud-currency").textContent = `${run.resources?.towerCurrency || 0} CARNE DA VOZ`;
