    if (floor.floor % 3 === 0) await chooseTowerUpgrade();
    run.floor += 1;
    run.floorSeed = null;
    run.playerPosition = null;
    run.clearedEncounters = [];
    run.openedChests = [];
    run.activatedAltars = [];
    run.completedEvents = [];
    run.activatedObjectives = [];
    run.explored = [];
    run.currentObjective = null;
    delete run.pendingEncounter;
    saveGame(state, "auto");
    fade.classList.add("tower-transition");
    await new Promise((resolve) => setTimeout(resolve, state.settings.reducedMotion ? 40 : 620));
