    const region = result.region, type = result.encounterType, towerWasUnlocked = state.tower.unlocked;
    state.currency += result.currency;
    const leveled = addXp(state, result.xp);
    if (leveled) toast("N\xEDvel aumentado", `Voc\xEA alcan\xE7ou o n\xEDvel ${state.level}.`, "good");
    const materialGain = type === "normal" ? 1 : type === "miniboss" ? 2 : 3;
    state.materials[region.key] += materialGain;
    showQuestUpdate(updateQuest(state, `side-${region.id}`, materialGain));
    const defeated = state.defeated[region.key];
    if (!defeated.includes(type)) {
      defeated.push(type);
      showQuestUpdate(updateQuest(state, `main-${region.id}`, 1));
    }
    if (type === "normal") showQuestUpdate(updateQuest(state, `hunt-${region.id}`, 1));
