      state.resonance = Math.min(100, state.resonance + 3);
      state.authority = state.maxAuthority;
      const unlocked = FORMS.filter((form) => form.unlock === region.id + 1);
      unlocked.forEach((form) => {
        if (!state.unlockedForms.includes(form.id)) state.unlockedForms.push(form.id);
      });
      if (unlocked[0] && !state.secondaryForm) state.secondaryForm = unlocked[0].id;
      if (region.id % 2 === 1) state.maxAuthority = Math.min(8, state.maxAuthority + 1);
      const newSkill = (ROUTES[state.route].commands.length + region.id) % 2 ? "summon" : "fracture";
      if (region.id >= 4 && !state.learnedSkills.includes(newSkill)) state.learnedSkills.push(newSkill);
